-- Immutable initial schema captured from the declarative database schema
-- immediately before tracked migrations were introduced.
CREATE TABLE "activities" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "output_id" integer NOT NULL, "indicator_id" integer, "state_id" integer, "locality_id" integer, "locality_name" text, "responsible_user_id" integer, "code" text NOT NULL, "title" text NOT NULL, "description" text, "target" numeric(14, 2) DEFAULT '0', "status" text DEFAULT 'planned' NOT NULL, "progress_pct" integer DEFAULT 0 NOT NULL, "planned_start" date, "planned_end" date, "budget_planned" numeric(14, 2) DEFAULT '0', "budget_spent" numeric(14, 2) DEFAULT '0' NOT NULL );
CREATE TABLE "ai_chat_messages" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer NOT NULL, "session_id" text NOT NULL, "role" text NOT NULL, "content" text NOT NULL, "module" text, "user_role" text, "status" text, "prompt_tokens" integer, "completion_tokens" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "ai_settings" ( "id" serial PRIMARY KEY NOT NULL, "enabled" text DEFAULT 'true' NOT NULL, "system_prompt_extra" text, "allowed_modules" text, "response_language" text DEFAULT 'auto' NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_by" integer );
CREATE TABLE "approvals" ( "id" serial PRIMARY KEY NOT NULL, "entity_type" text NOT NULL, "entity_id" integer NOT NULL, "action" text NOT NULL, "from_status" text NOT NULL, "to_status" text NOT NULL, "actor_id" integer NOT NULL, "comment" text, "timestamp" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "audit_log" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer, "action" text NOT NULL, "module" text NOT NULL, "entity_id" integer, "old_value" text, "new_value" text, "timestamp" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "beneficiaries" ( "id" serial PRIMARY KEY NOT NULL, "code" text NOT NULL, "name" text NOT NULL, "gender" text NOT NULL, "age_group" text NOT NULL, "category" text NOT NULL, "vulnerability" text, "state_id" integer NOT NULL, "locality_id" integer, "project_id" integer, "assistance_received" text, "date_of_assistance" date DEFAULT now() NOT NULL, "verification_status" text DEFAULT 'pending' NOT NULL );
CREATE TABLE "comments" ( "id" serial PRIMARY KEY NOT NULL, "entity_type" text NOT NULL, "entity_id" integer NOT NULL, "parent_id" integer, "section" text, "comment_type" text DEFAULT 'general' NOT NULL, "author_id" integer NOT NULL, "body" text NOT NULL, "status" text DEFAULT 'open' NOT NULL, "resolved_at" timestamp with time zone, "resolved_by_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "conversation_members" ( "id" serial PRIMARY KEY NOT NULL, "conversation_id" integer NOT NULL, "user_id" integer NOT NULL, "joined_at" timestamp with time zone DEFAULT now() NOT NULL, "last_read_at" timestamp with time zone, "is_admin" boolean DEFAULT false NOT NULL );
CREATE TABLE "conversations" ( "id" serial PRIMARY KEY NOT NULL, "type" text DEFAULT 'direct' NOT NULL, "name" text, "project_id" integer, "state_id" integer, "sector" text, "description" text, "created_by_id" integer NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "donors" ( "id" serial PRIMARY KEY NOT NULL, "name" text NOT NULL, "abbreviation" text, "country" text, "contact_name" text, "contact_email" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "drive_files" ( "id" serial PRIMARY KEY NOT NULL, "drive_file_id" text NOT NULL, "drive_link" text NOT NULL, "name" text NOT NULL, "mime_type" text NOT NULL, "size" integer, "module" text NOT NULL, "record_id" integer, "project_id" integer, "uploaded_by_user_id" integer NOT NULL, "user_role" text, "state_id" integer, "sector" text, "visibility_level" text DEFAULT 'internal' NOT NULL, "permission_level" text DEFAULT 'view' NOT NULL, "version_number" integer DEFAULT 1 NOT NULL, "parent_file_id" integer, "status" text DEFAULT 'active' NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "email_logs" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer, "email_to" text NOT NULL, "email_type" text NOT NULL, "subject" text, "status" text DEFAULT 'pending' NOT NULL, "provider_message_id" text, "error_message" text, "provider_name" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "sent_at" timestamp with time zone );
CREATE TABLE "email_verification_tokens" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer NOT NULL, "token_hash" text NOT NULL, "expires_at" timestamp with time zone NOT NULL, "used_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "ip_address" text, CONSTRAINT "email_verification_tokens_token_hash_unique" UNIQUE("token_hash") );
CREATE TABLE "idempotency_log" ( "id" serial PRIMARY KEY NOT NULL, "client_id" text NOT NULL, "operation" text NOT NULL, "status_code" integer NOT NULL, "response_body" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "expires_at" timestamp with time zone NOT NULL, CONSTRAINT "idempotency_log_client_id_unique" UNIQUE("client_id") );
CREATE TABLE "indicators" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "output_id" integer, "code" text NOT NULL, "title" text NOT NULL, "unit" text NOT NULL, "target" numeric(14, 2) NOT NULL, "achieved" numeric(14, 2) DEFAULT '0' NOT NULL, "sector" text NOT NULL );
CREATE TABLE "localities" ( "id" serial PRIMARY KEY NOT NULL, "state_id" integer NOT NULL, "name" text NOT NULL );
CREATE TABLE "manual_chapters" ( "id" serial PRIMARY KEY NOT NULL, "title" text NOT NULL, "slug" text NOT NULL, "description" text, "icon" text DEFAULT 'FileText' NOT NULL, "order" integer DEFAULT 0 NOT NULL, "language" text DEFAULT 'en' NOT NULL, "status" text DEFAULT 'published' NOT NULL, "created_by_id" integer, "updated_by_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "manual_sections" ( "id" serial PRIMARY KEY NOT NULL, "chapter_id" integer NOT NULL, "title" text NOT NULL, "content" text DEFAULT '' NOT NULL, "order" integer DEFAULT 0 NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "manual_sops" ( "id" serial PRIMARY KEY NOT NULL, "chapter_id" integer NOT NULL, "process_name" text NOT NULL, "purpose" text, "responsible_role" text, "steps" jsonb, "required_inputs" text, "approval_flow" text, "outputs" text, "timeline" text, "related_module" text, "notifications" text, "order" integer DEFAULT 0 NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "manual_version_history" ( "id" serial PRIMARY KEY NOT NULL, "chapter_id" integer NOT NULL, "section_id" integer, "previous_content" text, "updated_by_id" integer, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "message_mentions" ( "id" serial PRIMARY KEY NOT NULL, "message_id" integer NOT NULL, "mentioned_user_id" integer NOT NULL, "mentioned_by" integer NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "message_reactions" ( "id" serial PRIMARY KEY NOT NULL, "message_id" integer NOT NULL, "user_id" integer NOT NULL, "emoji" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "messages" ( "id" serial PRIMARY KEY NOT NULL, "conversation_id" integer NOT NULL, "sender_id" integer NOT NULL, "body" text NOT NULL, "attachments" jsonb, "reply_to_id" integer, "edited_at" timestamp with time zone, "deleted_at" timestamp with time zone, "deleted_by" integer, "deletion_type" text, "is_pinned" boolean DEFAULT false NOT NULL, "pinned_by" integer, "pinned_at" timestamp with time zone, "forwarded_from_message_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "notifications" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer NOT NULL, "kind" text NOT NULL, "entity_type" text, "entity_id" integer, "message" text NOT NULL, "link" text, "read_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "outputs" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "code" text NOT NULL, "title" text NOT NULL, "description" text, "target" numeric(14, 2) DEFAULT '0' );
CREATE TABLE "password_reset_tokens" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer NOT NULL, "token_hash" text NOT NULL, "expires_at" timestamp with time zone NOT NULL, "used_at" timestamp with time zone, "revoked_at" timestamp with time zone, "status" text DEFAULT 'active' NOT NULL, "source" text DEFAULT 'forgot_password' NOT NULL, "email_status" text DEFAULT 'pending' NOT NULL, "handled_by_id" integer, "handled_at" timestamp with time zone, "resolved_at" timestamp with time zone, "ip_address" text, "user_agent" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "password_reset_tokens_token_hash_unique" UNIQUE("token_hash") );
CREATE TABLE "plan_activities" ( "id" serial PRIMARY KEY NOT NULL, "plan_id" integer NOT NULL, "title" text NOT NULL, "description" text, "objective_index" integer, "responsible_user_id" integer, "responsible_name" text, "locality_name" text, "state_id" integer, "state_name" text, "planned_date" date, "target_beneficiaries" integer DEFAULT 0 NOT NULL, "priority" text DEFAULT 'medium' NOT NULL, "expected_result" text, "start_date" date, "end_date" date, "status" text DEFAULT 'planned' NOT NULL, "progress_pct" integer DEFAULT 0 NOT NULL, "budget_planned" numeric(14, 2) DEFAULT '0' NOT NULL, "budget_actual" numeric(14, 2) DEFAULT '0' NOT NULL, "risk_id" integer, "mitigation_action" text, "expected_output" text, "performance_indicator" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "plan_attachments" ( "id" serial PRIMARY KEY NOT NULL, "plan_id" integer NOT NULL, "file_name" text NOT NULL, "content_type" text NOT NULL, "size" integer DEFAULT 0 NOT NULL, "object_path" text NOT NULL, "uploaded_by_id" integer, "uploaded_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "plans" ( "id" serial PRIMARY KEY NOT NULL, "code" text NOT NULL, "title" text NOT NULL, "plan_type" text NOT NULL, "frequency" text DEFAULT 'monthly' NOT NULL, "project_id" integer, "state_id" integer NOT NULL, "locality_id" integer, "localities" jsonb DEFAULT '[]'::jsonb, "sector" text, "sectors" jsonb DEFAULT '[]'::jsonb, "responsible_name" text, "responsible_user_id" integer, "start_date" date NOT NULL, "end_date" date NOT NULL, "status" text DEFAULT 'draft' NOT NULL, "description" text, "objectives" jsonb DEFAULT '[]'::jsonb NOT NULL, "budget_planned" numeric(14, 2) DEFAULT '0' NOT NULL, "budget_actual" numeric(14, 2) DEFAULT '0' NOT NULL, "funding_source" text, "currency" text DEFAULT 'USD' NOT NULL, "created_by_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "version" integer DEFAULT 1 NOT NULL, "locked_by" integer, "locked_at" timestamp with time zone, CONSTRAINT "plans_code_unique" UNIQUE("code") );
CREATE TABLE "program_resources" ( "id" serial PRIMARY KEY NOT NULL, "title" text NOT NULL, "category" text NOT NULL, "sector" text NOT NULL, "description" text, "version_number" text, "effective_date" date, "tags" text, "file_name" text NOT NULL, "content_type" text, "file_size" integer, "object_path" text NOT NULL, "status" text DEFAULT 'active' NOT NULL, "uploaded_by_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "project_assignments" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "user_id" integer, "name" text, "role" text NOT NULL );
CREATE TABLE "project_documents" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "category" text DEFAULT 'optional' NOT NULL, "kind" text NOT NULL, "file_name" text NOT NULL, "content_type" text NOT NULL, "size" integer DEFAULT 0 NOT NULL, "object_path" text NOT NULL, "uploaded_by_id" integer, "uploaded_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "project_free_localities" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "name" text NOT NULL, "display_order" integer DEFAULT 0 NOT NULL );
CREATE TABLE "project_localities" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "locality_id" integer NOT NULL );
CREATE TABLE "project_state_allocations" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "state_id" integer NOT NULL, "budget_allocation" numeric(14, 2) DEFAULT '0' NOT NULL, "beneficiary_target" integer DEFAULT 0 NOT NULL, "beneficiary_male" integer DEFAULT 0 NOT NULL, "beneficiary_female" integer DEFAULT 0 NOT NULL, "beneficiary_boys" integer DEFAULT 0 NOT NULL, "beneficiary_girls" integer DEFAULT 0 NOT NULL, "activity_target" integer DEFAULT 0 NOT NULL, "indicator_target" integer DEFAULT 0 NOT NULL, "state_lead" text, "state_team" jsonb DEFAULT '[]'::jsonb, "notes" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "project_states" ( "id" serial PRIMARY KEY NOT NULL, "project_id" integer NOT NULL, "state_id" integer NOT NULL );
CREATE TABLE "projects" ( "id" serial PRIMARY KEY NOT NULL, "code" text NOT NULL, "title" text NOT NULL, "objective" text, "status" text DEFAULT 'draft' NOT NULL, "sector" text NOT NULL, "sectors" jsonb DEFAULT '[]'::jsonb, "classification" text, "donor" text NOT NULL, "donor_id" integer, "agreement_ref" text, "agreement_number" text, "agreement_start" date, "agreement_end" date, "signed_date" date, "internal_notes" text, "description" text, "start_date" date NOT NULL, "end_date" date NOT NULL, "budget_total" numeric(14, 2) DEFAULT '0' NOT NULL, "direct_cost" numeric(14, 2) DEFAULT '0', "indirect_cost" numeric(14, 2) DEFAULT '0', "cafa_contribution" numeric(14, 2) DEFAULT '0', "budget_version" text, "currency" text DEFAULT 'USD' NOT NULL, "beneficiaries_target" integer DEFAULT 0 NOT NULL, "beneficiaries_male" integer DEFAULT 0 NOT NULL, "beneficiaries_female" integer DEFAULT 0 NOT NULL, "beneficiaries_boys" integer DEFAULT 0 NOT NULL, "beneficiaries_girls" integer DEFAULT 0 NOT NULL, "activity_target" integer DEFAULT 0 NOT NULL, "indicator_target" integer DEFAULT 0 NOT NULL, "management_level" text DEFAULT 'hq_managed' NOT NULL, "created_by_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "version" integer DEFAULT 1 NOT NULL, "locked_by" integer, "locked_at" timestamp with time zone );
CREATE TABLE "reports" ( "id" serial PRIMARY KEY NOT NULL, "title" text NOT NULL, "kind" text NOT NULL, "report_type" text DEFAULT 'monthly' NOT NULL, "reporting_month" integer, "reporting_year" integer, "period_start" timestamp with time zone, "period_end" timestamp with time zone, "sector" text, "submitted_to" text, "status" text DEFAULT 'draft' NOT NULL, "project_id" integer, "state_id" integer, "period" text NOT NULL, "narrative" text, "executive_summary" text, "challenges" text, "recommendations" text, "sections" jsonb, "beneficiaries_male" integer DEFAULT 0, "beneficiaries_female" integer DEFAULT 0, "beneficiaries_boys" integer DEFAULT 0, "beneficiaries_girls" integer DEFAULT 0, "planned_budget" numeric(14, 2), "actual_expenditure" numeric(14, 2), "activities" jsonb, "quarter" integer, "on_demand_reason" text, "indicator_progress" jsonb, "submitted_by_id" integer NOT NULL, "submitted_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "version" integer DEFAULT 1 NOT NULL, "locked_by" integer, "locked_at" timestamp with time zone );
CREATE TABLE "risks" ( "id" serial PRIMARY KEY NOT NULL, "title" text NOT NULL, "description" text, "category" text NOT NULL, "severity" text NOT NULL, "likelihood" text NOT NULL, "status" text DEFAULT 'identified' NOT NULL, "state_id" integer NOT NULL, "project_id" integer, "plan_id" integer, "plan_activity_id" integer, "assigned_to_id" integer, "impact" text, "mitigation_plan" text, "due_date" date, "follow_up_date" date, "identified_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "version" integer DEFAULT 1 NOT NULL, "locked_by" integer, "locked_at" timestamp with time zone );
CREATE TABLE "states" ( "id" serial PRIMARY KEY NOT NULL, "name" text NOT NULL, "code" text NOT NULL, "manager_user_id" integer, "office_address" text );
CREATE TABLE "training_certificates" ( "id" serial PRIMARY KEY NOT NULL, "certificate_id" text NOT NULL, "user_id" integer NOT NULL, "training_video_id" integer NOT NULL, "issued_at" timestamp with time zone DEFAULT now() NOT NULL, "revoked_at" timestamp with time zone, "revoked_by_id" integer, "reissued_at" timestamp with time zone, "reissued_by_id" integer, "is_active" boolean DEFAULT true NOT NULL, CONSTRAINT "training_certificates_certificate_id_unique" UNIQUE("certificate_id") );
CREATE TABLE "training_completions" ( "id" serial PRIMARY KEY NOT NULL, "user_id" integer NOT NULL, "training_video_id" integer NOT NULL, "started_at" timestamp with time zone DEFAULT now() NOT NULL, "last_watched_at" timestamp with time zone DEFAULT now() NOT NULL, "completed_at" timestamp with time zone, "watch_percent" integer DEFAULT 0 NOT NULL, "completion_status" text DEFAULT 'not_started' NOT NULL, "total_watch_seconds" integer DEFAULT 0 NOT NULL, "last_position_seconds" integer DEFAULT 0 NOT NULL, "certificate_issued" boolean DEFAULT false NOT NULL );
CREATE TABLE "training_videos" ( "id" serial PRIMARY KEY NOT NULL, "title" text NOT NULL, "module_name" text NOT NULL, "role_access" text DEFAULT 'all' NOT NULL, "language" text DEFAULT 'ar' NOT NULL, "description" text, "file_path" text, "duration" integer, "status" text DEFAULT 'draft' NOT NULL, "generated_by" integer, "error_message" text, "progress_pct" integer DEFAULT 0, "progress_label" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL );
CREATE TABLE "users" ( "id" serial PRIMARY KEY NOT NULL, "name" text NOT NULL, "email" text NOT NULL, "username" text, "password_hash" text, "role" text NOT NULL, "role_label" text NOT NULL, "scope" text NOT NULL, "state_id" integer, "sector" text, "phone" text, "avatar_url" text, "job_title" text, "timezone" text DEFAULT 'Africa/Khartoum' NOT NULL, "notification_preferences" jsonb, "status" text DEFAULT 'active' NOT NULL, "language_preference" text DEFAULT 'en' NOT NULL, "last_login_at" timestamp with time zone, "invite_token" text, "invite_expires_at" timestamp with time zone, "invited_by_id" integer, "invite_email_status" text DEFAULT 'pending' NOT NULL, "invite_accepted_at" timestamp with time zone, "email_verified" boolean DEFAULT false NOT NULL, "email_verified_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "last_seen_at" timestamp with time zone );
CREATE TABLE "voice_notes" ( "id" serial PRIMARY KEY NOT NULL, "entity_type" text NOT NULL, "entity_id" integer NOT NULL, "file_name" text NOT NULL, "object_path" text NOT NULL, "content_type" text DEFAULT 'audio/webm' NOT NULL, "duration_seconds" integer DEFAULT 0 NOT NULL, "recorded_by_id" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL );
ALTER TABLE "program_resources" ADD CONSTRAINT "program_resources_uploaded_by_id_users_id_fk" FOREIGN KEY ("uploaded_by_id") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;